// Generated by `python3 scripts/build-mascot.py --emit-ts`: the converter the panel feeds to `python3 -`.
export const BUILD_MASCOT_PY: string = "#!/usr/bin/env python3\n\"\"\"Turn a GIF into the panel's mascot assets: hooks/mascot-assets.ts.\n\n    python3 scripts/build-mascot.py path/to/mascot.gif       # rewrite hooks/mascot-assets.ts (the built-in mascot)\n    python3 scripts/build-mascot.py path/to/any.gif --json   # print the same assets as JSON (the panel's \"Change mascot\")\n    python3 scripts/build-mascot.py --emit-ts                # copy this script into hooks/build-mascot-script.ts\n\nThe panel runs this script from hooks/build-mascot-script.ts (fed to `python3 -`), so it works wherever the\nplugin is installed. After editing this file, run it with --emit-ts to refresh that copy.\n\nNeeds ffmpeg. Writes, as base64 constants:\n  MASCOT_GIF    the animation, shrunk to fit an Svg source (desktop, while working)\n  MASCOT_STILL  its first frame as PNG (desktop, idle)\n  MASCOT_RASTER half-block cell frames (terminal; any truecolor terminal)\n\"\"\"\nimport base64, json, os, struct, subprocess, sys, tempfile\n\nSVG_BUDGET = 120_000          # Svg source limit is 131072 chars; leave room for the wrapper\nCOLS, PIX_ROWS, FPS = 22, 16, 8  # terminal: 22 columns \u00d7 8 rows, 8 frames a second\nDEFAULT = 0x01000000          # the terminal's own colour (lets near-black blend in)\n\n\ndef ff(*args: str) -> bytes:\n    return subprocess.run(['ffmpeg', '-v', 'error', '-y', *args], check=True, capture_output=True).stdout\n\n\ndef shrunk_gif(src: str, tmp: str) -> tuple[bytes, int]:\n    for width, colors, fps in [(140, 128, 15), (120, 96, 12), (100, 64, 12), (90, 48, 10), (72, 32, 8)]:\n        out = os.path.join(tmp, f'{width}.gif')\n        ff('-i', src, '-vf', f'fps={fps},scale={width}:-1:flags=lanczos,split[a][b];[a]palettegen=max_colors={colors}[p];[b][p]paletteuse=dither=bayer', '-loop', '0', out)\n        data = open(out, 'rb').read()\n        if len(base64.b64encode(data)) <= SVG_BUDGET:\n            return data, width\n    sys.exit('GIF too large even at 72px wide; trim it first')\n\n\ndef size_of(png: bytes) -> tuple[int, int]:\n    return struct.unpack('>II', png[16:24])\n\n\ndef raster_frames(src: str) -> list[str]:\n    raw = ff('-i', src, '-vf', f'fps={FPS},scale={COLS}:{PIX_ROWS}:flags=area', '-f', 'rawvideo', '-pix_fmt', 'rgb24', '-')\n    frame_len = COLS * PIX_ROWS * 3\n    frames = []\n    for f in range(len(raw) // frame_len):\n        px = raw[f * frame_len:(f + 1) * frame_len]\n\n        def color(x: int, y: int) -> int:\n            r, g, b = px[(y * COLS + x) * 3:(y * COLS + x) * 3 + 3]\n            return DEFAULT if r + g + b < 60 else (r << 16) | (g << 8) | b\n\n        cells = b''.join(\n            struct.pack('<III', 0x2580, color(x, 2 * row), color(x, 2 * row + 1))  # \u2580: top pixel fg, bottom pixel bg\n            for row in range(PIX_ROWS // 2) for x in range(COLS)\n        )\n        frames.append(base64.b64encode(cells).decode())\n    return frames\n\n\ndef here() -> str:\n    return os.path.dirname(os.path.abspath(__file__))  # only when run from the file, never via `python3 -`\n\n\ndef main() -> None:\n    if sys.argv[1:] == ['--emit-ts']:\n        target = os.path.join(here(), '..', 'hooks', 'build-mascot-script.ts')\n        with open(os.path.abspath(__file__)) as fh:\n            source = fh.read()\n        with open(target, 'w') as fh:\n            fh.write('// Generated by `python3 scripts/build-mascot.py --emit-ts`: the converter the panel feeds to `python3 -`.\\n')\n            fh.write(f'export const BUILD_MASCOT_PY: string = {json.dumps(source)}\\n')\n        print(f'wrote {os.path.normpath(target)}')\n        return\n    src = sys.argv[1]\n    as_json = '--json' in sys.argv[2:]\n    with tempfile.TemporaryDirectory() as tmp:\n        gif, width = shrunk_gif(src, tmp)\n        still_path = os.path.join(tmp, 'still.png')\n        ff('-i', src, '-vframes', '1', '-vf', f'scale={width}:-1:flags=lanczos', still_path)\n        still = open(still_path, 'rb').read()\n    w, h = size_of(still)\n    frames = raster_frames(src)\n    if as_json:\n        print(json.dumps({\n            'gif': base64.b64encode(gif).decode(), 'still': base64.b64encode(still).decode(), 'width': w, 'height': h,\n            'raster': {'columns': COLS, 'rows': PIX_ROWS // 2, 'frameMs': 1000 // FPS, 'frames': frames},\n        }))\n        return\n    out = os.path.join(here(), '..', 'hooks', 'mascot-assets.ts')\n    with open(out, 'w') as fh:\n        fh.write(f'// Generated by scripts/build-mascot.py from {os.path.basename(src)}; rerun it instead of editing.\\n')\n        fh.write(f'export const MASCOT_SIZE = {{ width: {w}, height: {h} }} as const\\n')\n        fh.write(f\"export const MASCOT_GIF = '{base64.b64encode(gif).decode()}'\\n\")\n        fh.write(f\"export const MASCOT_STILL = '{base64.b64encode(still).decode()}'\\n\")\n        fh.write(f'export const MASCOT_RASTER = {{\\n  columns: {COLS},\\n  rows: {PIX_ROWS // 2},\\n  frameMs: {1000 // FPS},\\n  frames: [\\n')\n        fh.writelines(f\"    '{fr}',\\n\" for fr in frames)\n        fh.write('  ],\\n}\\n')\n    print(f'gif {len(gif) // 1024}KB at {w}x{h}, still {len(still) // 1024}KB, {len(frames)} terminal frames -> {os.path.normpath(out)}')\n\n\nif __name__ == '__main__':\n    main()\n"
